void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Initialize variables
    int numVertices = target.getNumVertices();
    int numEdges = target.getNumEdges();
    List<GraphEdge> edges = new ArrayList<>();
    HashMap<Integer,GraphNode> nodeMap = new HashMap<>();

    // Add vertices to the graph
    for (int i = 0; i < numVertices; i++) {
        GraphNode node = new GraphNode(i);
        nodeMap.put(i, node);
        target.addVertex(node);
    }

    // Add edges to the graph
    for (int i = 0; i < numEdges; i++) {
        int u = StdRandom.uniform(numVertices);
        int v = StdRandom.uniform(numVertices);
        GraphEdge edge = new GraphEdge(u, v);
        edges.add(edge);
        target.addEdge(edge);
    }

    // Add the edges to the result map
    for (GraphEdge edge : edges) {
        resultMap.put(edge.toString(), edge);
    }
}

