private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Find the bucket with the minimum label
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);

    // Clear the bucket with the minimum label
    minBucket.clear();

    // Move all vertices from the bucket with the minimum label to the bucket with label 0
    for (Integer vertex : minBucket) {
        labels.set(vertex, 0);
    }

    // Update the labeling accordingly
    for (int i = minLabel + 1; i < bucketsByLabel.size(); i++) {
        Set<Integer> bucket = bucketsByLabel.get(i);
        for (Integer vertex : bucket) {
            labels.set(vertex, i - 1);
        }
    }
}

